/* MIT. User-defined solo dungeon services; destinations and fees are explicit. */
#include "dungeon_data53.h"
static int dungeon_count53(int tier){int count=0;for(unsigned i=0;i<DUNGEON_COUNT53;i++)if((int)dungeons53[i].tier==tier)count++;return count;}
static int dungeon_nth53(int tier,int row){for(unsigned i=0;i<DUNGEON_COUNT53;i++)if((int)dungeons53[i].tier==tier&&!row--)return i;return -1;}
static int dungeon_input53(CoreNpcUI53*u,Combat*g,const CoreNpc53*n,unsigned p){if(p&4){if(u->confirm)u->confirm=0;else u->mode=-1;return 0;}int rows=n->kind==4?dungeon_count53(u->tier):3;
 if(n->kind==4&&(p&(4096|8192))){u->tier=(u->tier+((p&4096)?3:1))%4;u->choice=u->confirm=0;return 0;}
 if(p&1024){u->choice=rows?(u->choice+rows-1)%rows:0;u->confirm=0;return 0;}if(p&2048){u->choice=rows?(u->choice+1)%rows:0;u->confirm=0;return 0;}if(!(p&2))return 0;if(n->kind==5&&u->choice==2){u->mode=-1;return 0;}if(!u->confirm){u->confirm=1;return 0;}u->confirm=0;
 if(n->kind==4){int id=dungeon_nth53(u->tier,u->choice);if(id<0)return 0;const Dungeon53*d=dungeons53+id;int fee=dungeonWarpFees53[d->tier];if(d->map==g->mapId){combat_notice(g,POP_SYSTEM,"You're already in that dungeon. No Zeny spent.");return 0;}if(g->zeny<fee){combat_notice(g,POP_ITEMS,"Warp requires %d Zeny. Nothing spent.",fee);return 0;}u->destination=id;u->mode=-2;return 0;/* Main charges only after successful world activation. */}
 int hpOnly=u->choice==1;if(g->hp==g->maxhp&&(hpOnly||g->sp==g->maxsp)&&(!combat_party_needs_recovery200||!combat_party_needs_recovery200(g,1,!hpOnly))){combat_notice(g,POP_SYSTEM,"You're already recovered. No Zeny spent.");return 0;}int fee=hpOnly?100:(int)n->storage;if(hpOnly&&g->zeny<100){fee=g->zeny;combat_notice(g,POP_SYSTEM,"You shouldn't suffer because you're short of Zeny. Let me help.");}else if(g->zeny<fee){combat_notice(g,POP_ITEMS,"Full recovery requires %d Zeny. HP-only healing is available.",fee);return 0;}if(combat_party_recover200&&!combat_party_recover200(g,1,!hpOnly)){combat_message(g,"Recovery could not be recorded. No Zeny spent.");return 0;}g->zeny-=fee;g->hp=g->maxhp;if(!hpOnly)g->sp=g->maxsp;if(fee>=100)combat_notice(g,POP_ITEMS,hpOnly?"HP restored for %d Zeny.":"HP/SP restored for %d Zeny.",fee);return 1;
}
